1	// Package chainledger implements the on-chain data governance core.
2	package chainledger
3	
4	import "sort"
5	
6	// Dataset is one ingestible on-chain data source with a declared schema version.
7	type Dataset struct {
8		Name          string
9		SchemaVersion int
10		Rows          int
11		Upstreams     []string
12	}
13	
14	// Lineage records where a dataset came from, so every derived table can be traced.
15	type Lineage struct {
16		Dataset  string
17		Parents  []string
18		Children []string
19	}
20	
21	// Register links a dataset into the lineage graph and rejects cycles.
22	//
23	// Re-registering an existing dataset replaces its direct upstreams with parents
24	// (de-duplicated, first occurrence wins, list order preserved) while keeping its
25	// existing direct downstreams. Reverse edges stay consistent: upstreams removed
26	// from the list drop the dataset from their children, newly added upstreams gain
27	// it at the end of their children, and retained upstreams keep exactly one entry
28	// in its original position.
29	//
30	// The whole request is validated before the graph is touched, so a rejected
31	// registration leaves every node, edge and ordering untouched. The parents slice
32	// is copied: mutating it after Register returns does not affect the graph.
33	func Register(graph map[string]*Lineage, dataset Dataset, parents []string) error {
34		if dataset.Name == "" {
35			return errInvalid("dataset name is required")
36		}
37	
38		// Validate up front, walking the request in input order so the first problem
39		// encountered is the one reported. No graph mutation happens in this loop.
40		upstreams := make([]string, 0, len(parents))
41		known := map[string]bool{}
42		for _, parent := range parents {
43			if parent == dataset.Name {
44				return errInvalid("dataset " + dataset.Name + " cannot be its own parent")
45			}
46			if _, ok := graph[parent]; !ok {
47				return errInvalid("unknown parent " + parent)
48			}
49			// A new edge dataset -> parent closes a cycle exactly when parent can
50			// already reach dataset through existing parent edges. This covers
51			// transitive paths of any depth, not only direct mutual references.
52			if reaches(graph, parent, dataset.Name) {
53				return errInvalid("cycle through " + parent + " for dataset " + dataset.Name)
54			}
55			if !known[parent] {
56				known[parent] = true
57				upstreams = append(upstreams, parent)
58			}
59		}
60	
61		entry, existed := graph[dataset.Name]
62		if !existed {
63			entry = &Lineage{Dataset: dataset.Name}
64		}
65	
66		// Remove reverse edges from upstreams the dataset no longer declares.
67		for _, old := range entry.Parents {
68			if known[old] {
69				continue
70			}
71			if p, ok := graph[old]; ok {
72				p.Children = removeChild(p.Children, dataset.Name)
73			}
74		}
75	
76		// Mirror every declared upstream exactly once. An existing edge keeps its
77		// position; a missing edge is appended after the current children.
78		for _, parent := range upstreams {
79			graph[parent].Children = addChildOnce(graph[parent].Children, dataset.Name)
80		}
81	
82		entry.Parents = upstreams
83		if !existed {
84			graph[dataset.Name] = entry
85		}
86		return nil
87	}
88	
89	// reaches reports whether target is reachable from node by following parent
90	// edges, i.e. whether target is among node's direct or transitive upstreams.
91	func reaches(graph map[string]*Lineage, from, target string) bool {
92		seen := map[string]bool{}
93		var walk func(string) bool
94		walk = func(node string) bool {
95			if node == target {
96				return true
97			}
98			if seen[node] {
99				return false
100			}
101			seen[node] = true
102			entry, ok := graph[node]
103			if !ok {
104				return false
105			}
106			for _, parent := range entry.Parents {
107				if walk(parent) {
108					return true
109				}
110			}
111			return false
112		}
113		return walk(from)
114	}
115	
116	// removeChild drops every occurrence of child from children, preserving the
117	// relative order of the remaining entries.
118	func removeChild(children []string, child string) []string {
119		out := children[:0]
120		for _, c := range children {
121			if c != child {
122				out = append(out, c)
123			}
124		}
125		return out
126	}
127	
128	// addChildOnce ensures child appears exactly once in children. An existing entry
129	// keeps its position (duplicate later entries are dropped); otherwise child is
130	// appended at the end.
131	func addChildOnce(children []string, child string) []string {
132		out := children[:0]
133		present := false
134		for _, c := range children {
135			if c == child {
136				if present {
137					continue
138				}
139				present = true
140			}
141			out = append(out, c)
142		}
143		if !present {
144			out = append(out, child)
145		}
146		return out
147	}
148	
149	// Impact names one dataset directly or indirectly downstream of an impact
150	// query's origin. Distance is the number of lineage edges on the shortest path
151	// from the origin to this dataset (a direct downstream has distance 1), and
152	// Path is that shortest path written from the origin to the dataset, one name
153	// per hop.
154	type Impact struct {
155		Dataset  string
156		Distance int
157		Path     []string
158	}
159	
160	// Impacts returns every dataset directly or indirectly downstream of origin,
161	// i.e. every dataset reachable from origin by following child edges. The origin
162	// itself is never listed, and datasets with no such connection never appear.
163	//
164	// Distance is the shortest edge count; each dataset is returned at most once
165	// even where several branches merge into it. When several shortest paths exist,
166	// the lexicographically smallest full path (name by name, Go string order) is
167	// reported. Results are ordered by distance and then by dataset name, never by
168	// registration order or the stored parent/child list order.
169	//
170	// The graph is read only: a successful or failed query changes no node, edge or
171	// ordering. The returned Path slices are independent copies, so mutating them
172	// cannot affect the graph. An empty origin is rejected as a missing name; an
173	// origin absent from the graph (including an empty or nil graph) is rejected
174	// with an error naming it and no partial results.
175	func Impacts(graph map[string]*Lineage, origin string) ([]Impact, error) {
176		if origin == "" {
177			return nil, errInvalid("dataset name is required")
178		}
179		if _, ok := graph[origin]; !ok {
180			return nil, errInvalid("dataset not found: " + origin)
181		}
182	
183		// BFS one distance level at a time. A node commits its distance and best
184		// (lexicographically smallest) shortest path only once the whole level is
185		// known, so candidates reaching the same child through different parents in
186		// the same level can be compared before either wins. Register rejects
187		// cycles, so a committed node is never reached again at an equal level.
188		distance := map[string]int{origin: 0}
189		best := map[string][]string{origin: {origin}}
190		frontier := []string{origin}
191		for d := 0; len(frontier) > 0; d++ {
192			nextDistance := d + 1
193			candidates := map[string][]string{}
194			var next []string
195			for _, node := range frontier {
196				for _, child := range graph[node].Children {
197					if _, seen := distance[child]; seen {
198						continue // reached on an earlier, strictly shorter level
199					}
200					// Fresh backing array per candidate: paths must not alias each
201					// other or any slice stored in the graph.
202					candidate := make([]string, len(best[node])+1)
203					copy(candidate, best[node])
204					candidate[len(candidate)-1] = child
205					if current, ok := candidates[child]; !ok || lessPath(candidate, current) {
206						if !ok {
207							next = append(next, child)
208						}
209						candidates[child] = candidate
210					}
211				}
212			}
213			for _, child := range next {
214				distance[child] = nextDistance
215				best[child] = candidates[child]
216			}
217			frontier = next
218		}
219	
220		impacts := make([]Impact, 0, len(distance)-1)
221		for name, d := range distance {
222			if name == origin {
223				continue
224			}
225			impacts = append(impacts, Impact{
226				Dataset:  name,
227				Distance: d,
228				Path:     append([]string(nil), best[name]...),
229			})
230		}
231		sort.Slice(impacts, func(i, j int) bool {
232			if impacts[i].Distance != impacts[j].Distance {
233				return impacts[i].Distance < impacts[j].Distance
234			}
235			return impacts[i].Dataset < impacts[j].Dataset
236		})
237		return impacts, nil
238	}
239	
240	// lessPath reports whether path a sorts before path b as a name sequence:
241	// names are compared with Go string order from the start, and an equal prefix
242	// makes the shorter path smaller.
243	func lessPath(a, b []string) bool {
244		for i := 0; i < len(a) && i < len(b); i++ {
245			if a[i] != b[i] {
246				return a[i] < b[i]
247			}
248		}
249		return len(a) < len(b)
250	}
251	
252	// Roots lists datasets with no parents, in stable order.
253	func Roots(graph map[string]*Lineage) []string {
254		var roots []string
255		for name, entry := range graph {
256			if len(entry.Parents) == 0 {
257				roots = append(roots, name)
258			}
259		}
260		sort.Strings(roots)
261		return roots
262	}
263	
264	type errInvalid string
265	
266	func (e errInvalid) Error() string { return string(e) }
