1	package chainledger
2	
3	import (
4		"reflect"
5		"slices"
6		"strings"
7		"testing"
8	)
9	
10	func mustRegister(t *testing.T, graph map[string]*Lineage, name string, parents ...string) {
11		t.Helper()
12		if err := Register(graph, Dataset{Name: name}, parents); err != nil {
13			t.Fatalf("Register(%s, %v): %v", name, parents, err)
14		}
15	}
16	
17	func sameStrings(got, want []string) bool {
18		if len(got) != len(want) {
19			return false
20		}
21		for i := range got {
22			if got[i] != want[i] {
23				return false
24			}
25		}
26		return true
27	}
28	
29	func assertEntry(t *testing.T, graph map[string]*Lineage, name string, wantParents, wantChildren []string) {
30		t.Helper()
31		entry, ok := graph[name]
32		if !ok {
33			t.Fatalf("dataset %q missing from graph", name)
34		}
35		if !sameStrings(entry.Parents, wantParents) {
36			t.Errorf("%s parents = %v, want %v", name, entry.Parents, wantParents)
37		}
38		if !sameStrings(entry.Children, wantChildren) {
39			t.Errorf("%s children = %v, want %v", name, entry.Children, wantChildren)
40		}
41	}
42	
43	// Every parent edge must be mirrored by exactly one matching child edge.
44	func assertConsistent(t *testing.T, graph map[string]*Lineage) {
45		t.Helper()
46		for name, entry := range graph {
47			counts := map[string]int{}
48			for _, c := range entry.Children {
49				counts[c]++
50				child, ok := graph[c]
51				if !ok {
52					t.Errorf("%s lists unknown child %s", name, c)
53					continue
54				}
55				if !slices.Contains(child.Parents, name) {
56					t.Errorf("%s is child of %s but has no matching parent edge", c, name)
57				}
58			}
59			for c, n := range counts {
60				if n != 1 {
61					t.Errorf("%s lists child %s %d times", name, c, n)
62				}
63			}
64			for _, p := range entry.Parents {
65				parent, ok := graph[p]
66				if !ok {
67					t.Errorf("%s lists unknown parent %s", name, p)
68					continue
69				}
70				if !slices.Contains(parent.Children, name) {
71					t.Errorf("%s is parent of %s but has no matching child edge", p, name)
72				}
73			}
74		}
75	}
76	
77	func TestRegisterBasicChainAndConsistency(t *testing.T) {
78		graph := map[string]*Lineage{}
79		mustRegister(t, graph, "raw")
80		mustRegister(t, graph, "detail", "raw")
