918	// Regression for a multi-path merge where comparing the full explanation path
919	// and comparing only the merge node's direct upstream name give different
920	// answers. source feeds a and b; a feeds z; b feeds c; report depends on z and
921	// c together (c declared ahead of z on purpose); view depends on report. From
922	// source both source->a->z->report and source->b->c->report have length 3. A
923	// rule that only compares the final upstream would wrongly prefer the c route
924	// (c < z); the full-path rule must compare from the origin and pick the a
925	// route, because the paths first differ at hop 1 where a < b. view inherits
926	// that explanation one hop further on.
927	func TestImpactsMergedBranchesFullPathTieBreak(t *testing.T) {
928		// Each sequence builds the same graph with a legal but different
929		// registration order; the second also flips report's upstream list, and the
930		// third registers the isolated node early. Names, distances and paths must
931		// come out identical regardless.
932		sequences := [][][]string{
933			{
934				{"source"},
935				{"b", "source"}, // b-side branch registered first
936				{"a", "source"},
937				{"c", "b"},
938				{"z", "a"},
939				{"report", "c", "z"}, // c listed ahead of z on purpose
940				{"view", "report"},
941				{"isolated"},
942			},
943			{
944				{"source"},
945				{"a", "source"}, // opposite branch registered first
946				{"z", "a"},
947				{"b", "source"},
948				{"c", "b"},
949				{"report", "z", "c"}, // direct-upstream order flipped
950				{"view", "report"},
951				{"isolated"},
952			},
953			{
954				{"source"},
955				{"isolated"},
956				{"b", "source"},
957				{"a", "source"},
958				{"z", "a"},
959				{"c", "b"},
960				{"report", "c", "z"},
961				{"view", "report"},
962			},
963		}
964	
965		want := []Impact{
966			{Dataset: "a", Distance: 1, Path: []string{"source", "a"}},
967			{Dataset: "b", Distance: 1, Path: []string{"source", "b"}},
968			{Dataset: "c", Distance: 2, Path: []string{"source", "b", "c"}},
969			{Dataset: "z", Distance: 2, Path: []string{"source", "a", "z"}},
970			{Dataset: "report", Distance: 3, Path: []string{"source", "a", "z", "report"}},
971			{Dataset: "view", Distance: 4, Path: []string{"source", "a", "z", "report", "view"}},
972		}
973	
974		for i, seq := range sequences {
975			graph := buildRegisteredGraph(t, seq)
976			assertConsistent(t, graph)
977			before := snapshot(graph)
978	
979			impacts := mustImpacts(t, graph, "source")
980			if !reflect.DeepEqual(impacts, want) {
981				t.Fatalf("sequence %d: impacts = %v, want %v", i, impacts, want)
982			}
983	
984			// Anchors with explicit messages: the merge node is explained exactly
985			// once through a/z even though c sorts ahead of z, and view continues
986			// along that same route.
987			assertImpactOnce(t, impacts, "report", 3, []string{"source", "a", "z", "report"})
988			assertImpactOnce(t, impacts, "view", 4, []string{"source", "a", "z", "report", "view"})
989	
990			// The origin itself and an unconnected dataset never appear.
991			if names := impactNames(impacts); slices.Contains(names, "source") || slices.Contains(names, "isolated") {
992				t.Fatalf("sequence %d: origin or isolated dataset leaked into %v", i, names)
993			}
994	
995			// The query changes no node, relationship or stored list order.
996			if !reflect.DeepEqual(snapshot(graph), before) {
997				t.Fatalf("sequence %d: query changed graph: before=%v after=%v", i, before, snapshot(graph))
998			}
999		}
1000	}
