1031					{"a", "source"},
1032					{"z", "a"},
1033					{"b", "source"},
1034					{"c", "b"},
1035					{"report", "z", "c"},
1036					{"view", "report"},
1037					{"isolated"},
1038				},
1039				newParents: []string{"c", "z", "source"}, // direct edge last
1040			},
1041		}
1042	
1043		want := []Impact{
1044			{Dataset: "a", Distance: 1, Path: []string{"source", "a"}},
1045			{Dataset: "b", Distance: 1, Path: []string{"source", "b"}},
1046			{Dataset: "report", Distance: 1, Path: []string{"source", "report"}},
1047			{Dataset: "c", Distance: 2, Path: []string{"source", "b", "c"}},
1048			{Dataset: "view", Distance: 2, Path: []string{"source", "report", "view"}},
1049			{Dataset: "z", Distance: 2, Path: []string{"source", "a", "z"}},
1050		}
