1070			assertImpact(t, impacts, "c", 2, []string{"source", "b", "c"})
1071	
1072			if names := impactNames(impacts); slices.Contains(names, "source") || slices.Contains(names, "isolated") {
1073				t.Fatalf("build %d: origin or isolated dataset leaked into %v", i, names)
1074			}
1075			if !reflect.DeepEqual(snapshot(graph), before) {
1076				t.Fatalf("build %d: query changed graph: before=%v after=%v", i, before, snapshot(graph))
