1098		if err == nil || !strings.Contains(err.Error(), "ghost") {
1099			t.Fatalf("want unknown-parent error naming ghost, got %v", err)
1100		}
1101	
1102		// Cyclic upstream: pointing mid at its own downstream leaf must name leaf.
1103		err = Register(graph, Dataset{Name: "mid"}, []string{"leaf"})
1104		if err == nil || !strings.Contains(err.Error(), "cycle") || !strings.Contains(err.Error(), "leaf") {
1105			t.Fatalf("want cycle error naming leaf, got %v", err)
1106		}
