1112			t.Fatalf("raw impacts changed after rejected re-wires: got %v, want %v", got, rawBefore)
1113		}
1114		if got := mustImpacts(t, graph, "newsrc"); !reflect.DeepEqual(got, newBefore) {
1115			t.Fatalf("newsrc impacts changed after rejected re-wires: got %v, want %v", got, newBefore)
1116		}
